import AdminEnhanced from "./AdminEnhanced";
import { cn } from "@/lib/utils";
import { Award, CirclePlus, Download, Filter, Gift, MessageCircle, Search, Trash2, Upload } from "lucide-react";
import { useState, type FormEvent } from "react";
import { toast } from "sonner";
import type { AppConfig, ContentContext, ContentImportEnvelope, ContentKind, ContentModule, ContentTone, CustomAchievement, CustomContentItem, Encouragement, HistoricalCharacter, MascotStateItem, StudyAccount, WheelReward } from "../../../shared/study";

type Props = { account: StudyAccount; config: AppConfig; onConfig: (config: AppConfig, message?: string) => void };
type AchievementMetric = CustomAchievement["metric"];
type RewardKind = WheelReward["kind"];

const uid = () => crypto.randomUUID();
const downloadFile = (filename: string, content: string, type: string) => { const blob = new Blob([content], { type }); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = filename; link.click(); URL.revokeObjectURL(url); };
const csvCell = (value: unknown) => `"${String(value ?? "").replaceAll('"', '""')}"`;
const parseCsvLine = (line: string) => { const values: string[] = []; let current = ""; let quoted = false; for (let index = 0; index < line.length; index += 1) { const char = line[index]; if (char === '"' && line[index + 1] === '"' && quoted) { current += '"'; index += 1; } else if (char === '"') quoted = !quoted; else if (char === ',' && !quoted) { values.push(current); current = ""; } else current += char; } values.push(current); return values; };

export default function AdminContentHub({ account, config, onConfig }: Props) {
  const [encouragementText, setEncouragementText] = useState("");
  const [encouragementType, setEncouragementType] = useState<Encouragement["type"]>("correct");
  const [contentDraft, setContentDraft] = useState<{ kind: ContentKind; text: string; contexts: ContentContext[]; modules: ContentModule[]; mascot: "lumi" | "lumi-sad" | "lumi-cheer" | "lumi-celebrate" | "ong"; tone: ContentTone }>({ kind: "comfort", text: "", contexts: ["tired"], modules: ["global"], mascot: "lumi", tone: "gentle" });
  const [achievement, setAchievement] = useState({ name: "", description: "", metric: "xp" as AchievementMetric, threshold: "100", rewardXp: "30", rewardFragments: "0", title: "", titleMeaning: "", lumiImageUrl: "" });
  const [reward, setReward] = useState({ label: "", kind: "xp" as RewardKind, value: "20", probability: "10", color: "#d99a28" });
  const [ticketGrant, setTicketGrant] = useState(String(config.wheelTicketsPerAchievement ?? 1));
  const [selectedContentIds, setSelectedContentIds] = useState<string[]>([]);
  const [selectedMascotIds, setSelectedMascotIds] = useState<string[]>([]);
  const [contentQuery, setContentQuery] = useState("");
  const [contentModuleFilter, setContentModuleFilter] = useState<ContentModule | "all">("all");
  const [contentKindFilter, setContentKindFilter] = useState<ContentKind | "all">("all");
  const [contentStatusFilter, setContentStatusFilter] = useState<"all" | "active" | "hidden" | "trash" | "ai">("all");
  const [mascotDraft, setMascotDraft] = useState({ id: "idle", name: "", description: "", condition: "", imageUrl: "" });
  const allowed = account.role === "Admin" || account.role === "Founder";
  const save = (patch: Partial<AppConfig>, message: string) => onConfig({ ...config, ...patch, updatedAt: new Date().toISOString() }, message);

  if (!allowed) return <AdminEnhanced account={account} config={config} onConfig={onConfig} />;

  const addCustomContent = () => {
    const text = contentDraft.text.trim();
    if (!text || !contentDraft.contexts.length || !contentDraft.modules.length) return toast.error("Nhập nội dung, chọn ngữ cảnh và ít nhất một module.");
    save({ customContent: [...(config.customContent ?? []), { id: uid(), ...contentDraft, text, enabled: true, createdAt: new Date().toISOString(), useCount: 0 }] }, "Đã thêm nội dung vào kho của Lumi.");
    setContentDraft({ kind: "comfort", text: "", contexts: ["tired"], modules: ["global"], mascot: "lumi", tone: "gentle" });
  };
  const toggleContentContext = (context: ContentContext) => setContentDraft((draft) => ({ ...draft, contexts: draft.contexts.includes(context) ? draft.contexts.filter((item) => item !== context) : [...draft.contexts, context] }));
  const toggleContentModule = (module: ContentModule) => setContentDraft((draft) => ({ ...draft, modules: draft.modules.includes(module) ? draft.modules.filter((item) => item !== module) : [...draft.modules, module] }));
  const contentItems = config.customContent ?? [];
  const trashContent = (ids: string[]) => save({ customContent: contentItems.map((item) => ids.includes(item.id) ? { ...item, enabled: false, deletedAt: new Date().toISOString() } : item) }, "Đã chuyển nội dung vào thùng rác.");
  const restoreContent = (ids: string[]) => save({ customContent: contentItems.map((item) => ids.includes(item.id) ? { ...item, enabled: true, deletedAt: undefined } : item) }, "Đã khôi phục nội dung.");
  const permanentlyDeleteContent = (ids: string[]) => { if (!window.confirm("Xóa vĩnh viễn nội dung đã chọn? Hành động này không thể hoàn tác.")) return; save({ customContent: contentItems.filter((item) => !ids.includes(item.id)) }, "Đã xóa vĩnh viễn nội dung."); setSelectedContentIds([]); };
  const visibleContentItems = contentItems.filter((item) => {
    const query = contentQuery.trim().toLocaleLowerCase();
    const matchesQuery = !query || item.text.toLocaleLowerCase().includes(query) || item.kind.toLocaleLowerCase().includes(query) || item.modules.some((module) => module.toLocaleLowerCase().includes(query));
    const matchesModule = contentModuleFilter === "all" || item.modules.includes(contentModuleFilter);
    const matchesKind = contentKindFilter === "all" || item.kind === contentKindFilter;
    const matchesStatus = contentStatusFilter === "all" || (contentStatusFilter === "trash" ? Boolean(item.deletedAt) : contentStatusFilter === "ai" ? item.approvalStatus === "ai_suggestion" : !item.deletedAt && (contentStatusFilter === "active" ? item.enabled : !item.enabled));
    return matchesQuery && matchesModule && matchesKind && matchesStatus;
  });
  const exportContent = (format: "json" | "csv") => {
    if (format === "json") { const envelope: ContentImportEnvelope = { version: 1, exportedAt: new Date().toISOString(), app: "gocnhocuaong", items: contentItems }; downloadFile(`gocnhocuaong-content-${Date.now()}.json`, JSON.stringify(envelope, null, 2), "application/json"); }
    else { const rows = [["id", "kind", "text", "contexts", "modules", "mascot", "tone", "enabled", "approvalStatus", "source", "createdAt", "deletedAt"], ...contentItems.map((item) => [item.id, item.kind, item.text, item.contexts.join("|"), item.modules.join("|"), item.mascot, item.tone, item.enabled, item.approvalStatus ?? "approved", item.source ?? "ong", item.createdAt ?? "", item.deletedAt ?? ""])]; downloadFile(`gocnhocuaong-content-${Date.now()}.csv`, rows.map((row) => row.map(csvCell).join(",")).join("\n"), "text/csv;charset=utf-8"); }
  };
  const importContent = (event: React.ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { try { const raw = String(reader.result); let items: CustomContentItem[]; if (file.name.toLowerCase().endsWith(".csv")) { const lines = raw.split(/\r?\n/).filter(Boolean); const headers = lines.shift()?.split(",") ?? []; if (!headers.includes("text") || !headers.includes("kind")) throw new Error("Thiếu cột bắt buộc"); items = lines.map((line) => { const values = parseCsvLine(line); const row = Object.fromEntries(headers.map((header, index) => [header, values[index] ?? ""])); return { id: String(row.id || uid()), kind: String(row.kind) as ContentKind, text: String(row.text), contexts: String(row.contexts || "").split("|").filter(Boolean) as ContentContext[], modules: String(row.modules || "global").split("|").filter(Boolean) as ContentModule[], mascot: (String(row.mascot || "lumi") as CustomContentItem["mascot"]), tone: (String(row.tone || "gentle") as ContentTone), enabled: String(row.enabled).toLowerCase() !== "false", createdAt: String(row.createdAt || new Date().toISOString()), deletedAt: undefined, source: "import", approvalStatus: "approved" }; }); } else { const parsed = JSON.parse(raw) as ContentImportEnvelope; if (parsed.app !== "gocnhocuaong" || parsed.version !== 1 || !Array.isArray(parsed.items)) throw new Error("Định dạng không hợp lệ"); items = parsed.items.filter((item) => item && typeof item.id === "string" && typeof item.text === "string"); } const imported = items.map((item) => ({ ...item, id: uid(), source: "import" as const, approvalStatus: "approved" as const, createdAt: item.createdAt ?? new Date().toISOString(), deletedAt: undefined })); save({ customContent: [...contentItems, ...imported] }, `Đã nhập ${imported.length} nội dung vào kho.`); } catch { toast.error("Không thể nhập file. Kiểm tra JSON/CSV xuất từ Góc học tập của Ong."); } finally { event.target.value = ""; } }; reader.readAsText(file); };
  const approveAiSuggestion = (id: string) => save({ customContent: contentItems.map((item) => item.id === id ? { ...item, approvalStatus: "approved" as const, source: "ong" as const } : item) }, "Đã thêm đề xuất vào kho chính.");
  const mascotItems = config.mascotStates ?? [];
  const addMascotState = () => {
    const draft = { ...mascotDraft, id: mascotDraft.id.trim() || uid(), name: mascotDraft.name.trim(), description: mascotDraft.description.trim(), condition: mascotDraft.condition.trim(), imageUrl: mascotDraft.imageUrl.trim() || undefined };
    if (!draft.name || !draft.description || !draft.condition) return toast.error("Nhập tên, mô tả và điều kiện mascot.");
    const entry: MascotStateItem = { ...draft, enabled: true, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() };
    save({ mascotStates: [...mascotItems.filter((item) => item.id !== entry.id), entry] }, "Đã lưu trạng thái mascot.");
    setMascotDraft({ id: "idle", name: "", description: "", condition: "", imageUrl: "" });
  };
  const updateMascot = (id: string) => {
    const current = mascotItems.find((item) => item.id === id);
    if (!current) return;
    const name = window.prompt("Tên trạng thái mascot", current.name);
    if (name == null) return;
    const description = window.prompt("Mô tả", current.description);
    if (description == null) return;
    const condition = window.prompt("Điều kiện sử dụng", current.condition);
    if (condition == null) return;
    const imageUrl = window.prompt("URL ảnh mascot (để trống dùng fallback)", current.imageUrl ?? "");
    if (imageUrl == null) return;
    save({ mascotStates: mascotItems.map((item) => item.id === id ? { ...item, name: name.trim() || item.name, description: description.trim() || item.description, condition: condition.trim() || item.condition, imageUrl: imageUrl.trim() || undefined, updatedAt: new Date().toISOString() } : item) }, "Đã cập nhật trạng thái mascot.");
  };
  const trashMascot = (ids: string[]) => save({ mascotStates: mascotItems.map((item) => ids.includes(item.id) ? { ...item, enabled: false, deletedAt: new Date().toISOString(), updatedAt: new Date().toISOString() } : item) }, "Đã chuyển mascot vào thùng rác.");
  const restoreMascot = (ids: string[]) => save({ mascotStates: mascotItems.map((item) => ids.includes(item.id) ? { ...item, enabled: true, deletedAt: undefined, updatedAt: new Date().toISOString() } : item) }, "Đã khôi phục mascot.");
  const permanentlyDeleteMascot = (ids: string[]) => { if (!window.confirm("Xóa vĩnh viễn mascot đã chọn? Hành động này không thể hoàn tác.")) return; save({ mascotStates: mascotItems.filter((item) => !ids.includes(item.id)) }, "Đã xóa vĩnh viễn mascot."); setSelectedMascotIds([]); };

  const addEncouragement = () => {
    const text = encouragementText.trim();
    if (!text) return toast.error("Nhập nội dung lời động viên.");
    const entry: Encouragement = { id: uid(), type: encouragementType, text, enabled: true };
    save({ encouragements: [...config.encouragements, entry] }, "Đã thêm lời động viên.");
    setEncouragementText("");
  };
  const addAchievement = () => {
    const name = achievement.name.trim();
    const threshold = Math.max(1, Number(achievement.threshold) || 0);
    if (!name || !threshold) return toast.error("Nhập tên và mốc điều kiện hợp lệ.");
    const entry: CustomAchievement = {
      id: uid(), name, description: achievement.description.trim() || `Đạt ${threshold} ${achievement.metric}.`, metric: achievement.metric,
      threshold, rewardXp: Math.max(0, Number(achievement.rewardXp) || 0), rewardFragments: Math.max(0, Number(achievement.rewardFragments) || 0), title: achievement.title.trim() || undefined, titleMeaning: achievement.titleMeaning.trim() || undefined, lumiImageUrl: achievement.lumiImageUrl.trim() || undefined, enabled: true,
    };
    save({ customAchievements: [...config.customAchievements, entry] }, "Đã thêm thành tích tùy chỉnh.");
    setAchievement({ name: "", description: "", metric: "xp", threshold: "100", rewardXp: "30", rewardFragments: "0", title: "", titleMeaning: "", lumiImageUrl: "" });
  };
  const saveTicketGrant = () => {
    const value = Math.max(0, Math.floor(Number(ticketGrant) || 0));
    save({ wheelTicketsPerAchievement: value }, `Mỗi mốc có mảnh ghép sẽ cấp ${value} vé quay.`);
  };
  const addReward = () => {
    const label = reward.label.trim();
    if (!label) return toast.error("Nhập tên phần thưởng.");
    const entry: WheelReward = { id: uid(), label, kind: reward.kind, value: Math.max(0, Number(reward.value) || 0), probability: Math.max(0, Number(reward.probability) || 0), color: reward.color };
    save({ wheelRewards: [...config.wheelRewards, entry] }, "Đã thêm phần thưởng vòng quay.");
    setReward({ label: "", kind: "xp", value: "20", probability: "10", color: "#d99a28" });
  };

  return <>
    <AdminEnhanced account={account} config={config} onConfig={onConfig} />
    <section className="mt-7 grid gap-5 xl:grid-cols-4" aria-label="Quản lý động cơ học tập">
      <EditorCard icon={MessageCircle} eyebrow="Phản hồi học tập" title="Lời động viên" text="Dùng cho kết quả đúng hoặc chưa đúng; chỉ nội dung được quản trị mới xuất hiện cho người học.">
        <div className="space-y-3"><select aria-label="Loại lời động viên" value={encouragementType} onChange={(event) => setEncouragementType(event.target.value as Encouragement["type"])} className="input"><option value="correct">Khi trả lời đúng</option><option value="incorrect">Khi trả lời chưa đúng</option></select><textarea aria-label="Nội dung lời động viên" value={encouragementText} onChange={(event) => setEncouragementText(event.target.value)} className="input min-h-20" placeholder="Viết lời khích lệ ngắn, cụ thể và tôn trọng người học." /><button className="primary-button w-full" onClick={addEncouragement}><CirclePlus className="h-4 w-4" />Thêm lời động viên</button></div>
        <ConfigRows rows={config.encouragements.map((entry) => ({ id: entry.id, title: entry.text, meta: entry.type === "correct" ? "Trả lời đúng" : "Trả lời chưa đúng", enabled: entry.enabled }))} onToggle={(id) => save({ encouragements: config.encouragements.map((entry) => entry.id === id ? { ...entry, enabled: !entry.enabled } : entry) }, "Đã cập nhật trạng thái lời động viên.")} onDelete={(id) => save({ encouragements: config.encouragements.filter((entry) => entry.id !== id) }, "Đã xóa lời động viên.")} />
      </EditorCard>
      <EditorCard icon={Award} eyebrow="Thành tích và phần thưởng" title="Mốc tùy chỉnh" text="Hệ 900 thành tích giữ quy tắc chuẩn; thêm mốc riêng cho chương trình hoặc thử thách do bạn biên tập.">
        <div className="grid gap-3"><input aria-label="Tên thành tích tùy chỉnh" value={achievement.name} onChange={(event) => setAchievement({ ...achievement, name: event.target.value })} className="input" placeholder="Tên thành tích" /><input aria-label="Mô tả thành tích tùy chỉnh" value={achievement.description} onChange={(event) => setAchievement({ ...achievement, description: event.target.value })} className="input" placeholder="Mô tả ngắn" /><input aria-label="Danh hiệu thành tích tùy chỉnh" value={achievement.title} onChange={(event) => setAchievement({ ...achievement, title: event.target.value })} className="input" placeholder="Danh hiệu nếu có" /><input aria-label="Ý nghĩa danh hiệu tùy chỉnh" value={achievement.titleMeaning} onChange={(event) => setAchievement({ ...achievement, titleMeaning: event.target.value })} className="input" placeholder="Ý nghĩa danh hiệu" /><input aria-label="URL ảnh Lumi cho thành tích" value={achievement.lumiImageUrl} onChange={(event) => setAchievement({ ...achievement, lumiImageUrl: event.target.value })} className="input" placeholder="URL ảnh Lumi riêng (tùy chọn)" /><div className="grid grid-cols-2 gap-3"><select aria-label="Chỉ số thành tích tùy chỉnh" value={achievement.metric} onChange={(event) => setAchievement({ ...achievement, metric: event.target.value as AchievementMetric })} className="input"><option value="xp">XP</option><option value="learnedCards">Thẻ đã nhớ</option><option value="completedQuizzes">Đề hoàn thành</option><option value="completedSets">Bộ hoàn tất</option></select><input aria-label="Mốc điều kiện thành tích" value={achievement.threshold} onChange={(event) => setAchievement({ ...achievement, threshold: event.target.value })} type="number" min="1" className="input" placeholder="Mốc" /></div><div className="grid grid-cols-2 gap-3"><input aria-label="XP phần thưởng thành tích" value={achievement.rewardXp} onChange={(event) => setAchievement({ ...achievement, rewardXp: event.target.value })} type="number" min="0" className="input" placeholder="XP" /><input aria-label="Mảnh ghép phần thưởng thành tích" value={achievement.rewardFragments} onChange={(event) => setAchievement({ ...achievement, rewardFragments: event.target.value })} type="number" min="0" className="input" placeholder="Mảnh ghép" /></div><button className="primary-button w-full" onClick={addAchievement}><CirclePlus className="h-4 w-4" />Thêm mốc tùy chỉnh</button></div>
        <ConfigRows rows={config.customAchievements.map((entry) => ({ id: entry.id, title: entry.name, meta: `${entry.threshold} ${entry.metric} · ${entry.rewardXp} XP · ${entry.rewardFragments} mảnh${entry.lumiImageUrl ? " · có ảnh Lumi" : ""}`, enabled: entry.enabled }))} onToggle={(id) => save({ customAchievements: config.customAchievements.map((entry) => entry.id === id ? { ...entry, enabled: !entry.enabled } : entry) }, "Đã cập nhật trạng thái thành tích.")} onDelete={(id) => save({ customAchievements: config.customAchievements.filter((entry) => entry.id !== id) }, "Đã xóa thành tích tùy chỉnh.")} />
      </EditorCard>
      <EditorCard icon={MessageCircle} eyebrow="Kho lời nói & ý tưởng" title="＋ Thêm nội dung" text="Tạo lời an ủi, nhiệm vụ siêu nhỏ, lời nhắc nhẹ hoặc lựa chọn chống trì hoãn cho Lumi.">
        <div className="mb-4 rounded-2xl border border-[#2e7d32]/20 bg-[#f7fff7] p-3 dark:border-emerald-400/20 dark:bg-emerald-950/20"><div className="flex flex-wrap gap-2"><label className="relative min-w-[220px] flex-1"><Search className="pointer-events-none absolute left-3 top-3 h-4 w-4 text-slate-400" /><input aria-label="Tìm kiếm kho nội dung" value={contentQuery} onChange={(event) => setContentQuery(event.target.value)} className="input pl-9" placeholder="Tìm lời nói, nhiệm vụ, module..." /></label><select aria-label="Lọc module nội dung" value={contentModuleFilter} onChange={(event) => setContentModuleFilter(event.target.value as ContentModule | "all")} className="input max-w-44"><option value="all">Tất cả module</option><option value="pomodoro">Pomodoro</option><option value="quiz">Làm đề</option><option value="deepStudy">Hiểu bài</option><option value="achievement">Thành tích</option><option value="journal">Nhật ký</option><option value="antiProcrastination">Chống trì hoãn</option><option value="global">Dùng chung</option></select><select aria-label="Lọc loại nội dung" value={contentKindFilter} onChange={(event) => setContentKindFilter(event.target.value as ContentKind | "all")} className="input max-w-44"><option value="all">Tất cả loại</option><option value="comfort">An ủi</option><option value="encouragement">Động viên</option><option value="studyHint">Gợi ý học</option><option value="antiProcrastination">Chống trì hoãn</option><option value="microTask">Nhiệm vụ</option><option value="reminder">Lời nhắc</option><option value="choice">Lựa chọn</option><option value="other">Khác</option></select><select aria-label="Lọc trạng thái nội dung" value={contentStatusFilter} onChange={(event) => setContentStatusFilter(event.target.value as typeof contentStatusFilter)} className="input max-w-40"><option value="all">Mọi trạng thái</option><option value="active">Đang dùng</option><option value="hidden">Tạm ẩn</option><option value="trash">Thùng rác</option><option value="ai">AI chờ duyệt</option></select></div><div className="mt-3 flex flex-wrap gap-2"><button type="button" className="secondary-button" onClick={() => exportContent("json")}><Download className="h-4 w-4" />Xuất JSON</button><button type="button" className="secondary-button" onClick={() => exportContent("csv")}><Download className="h-4 w-4" />Xuất CSV</button><label className="secondary-button cursor-pointer"><Upload className="h-4 w-4" />Nhập JSON<input aria-label="Nhập kho nội dung JSON" type="file" accept="application/json,text/csv,.json,.csv" className="hidden" onChange={importContent} /></label><span className="ml-auto inline-flex items-center gap-1 text-xs font-bold text-slate-500"><Filter className="h-3.5 w-3.5" />{visibleContentItems.length}/{contentItems.length} mục</span></div></div><div className="mb-4 rounded-2xl border border-amber-300/50 bg-amber-50 p-3 dark:border-amber-300/20 dark:bg-amber-950/20"><p className="text-xs font-bold uppercase tracking-wide text-amber-800 dark:text-amber-200">💡 AI đề xuất · chưa phải nội dung chính thức</p><p className="mt-1 text-xs text-amber-700 dark:text-amber-100">AI không được tự sửa hoặc xóa kho của Ong. Chỉ nút “Thêm vào kho” mới duyệt đề xuất.</p>{contentItems.filter((item) => item.approvalStatus === "ai_suggestion" && !item.deletedAt).map((item) => <div key={item.id} className="mt-2 flex items-start justify-between gap-2 rounded-xl bg-white/80 p-2 dark:bg-black/20"><span className="text-sm">{item.text}</span><button type="button" className="secondary-button shrink-0" onClick={() => approveAiSuggestion(item.id)}>Thêm vào kho</button></div>)}</div><div className="grid gap-3"><select aria-label="Loại nội dung mới" value={contentDraft.kind} onChange={(event) => setContentDraft({ ...contentDraft, kind: event.target.value as ContentKind })} className="input"><option value="comfort">💛 Lời an ủi</option><option value="encouragement">🔥 Động viên</option><option value="studyHint">🧠 Gợi ý học</option><option value="antiProcrastination">🫠 Chống trì hoãn</option><option value="microTask">🎯 Nhiệm vụ</option><option value="reminder">🌱 Lời nhắc</option><option value="choice">🎲 Lựa chọn</option><option value="other">✨ Khác</option></select><textarea aria-label="Nội dung mới" value={contentDraft.text} onChange={(event) => setContentDraft({ ...contentDraft, text: event.target.value })} className="input min-h-24" placeholder="Ví dụ: Mở sách và đọc đúng một định nghĩa thôi nhé." /><div><p className="text-xs font-bold text-slate-500">Ngữ cảnh sử dụng · chọn nhiều</p><div className="mt-2 flex flex-wrap gap-1.5">{([['mistake','Sai bài'],['lowScore','Điểm thấp'],['procrastination','Trì hoãn'],['start','Bắt đầu học'],['pomodoroComplete','Xong Pomodoro'],['tired','Mệt'],['sad','Buồn'],['lostStreak','Mất streak'],['comeback','Quay lại'],['achievement','Đạt thành tích'],['confused','Không hiểu bài'],['taskComplete','Xong nhiệm vụ']] as [ContentContext,string][]).map(([value,label]) => <button key={value} type="button" onClick={() => toggleContentContext(value)} className={`rounded-lg px-2 py-1 text-[10px] font-bold ${contentDraft.contexts.includes(value) ? 'bg-[#c62828] text-white' : 'bg-[#eff9ef] text-[#2e7d32]'}`}>{label}</button>)}</div></div><div><p className="text-xs font-bold text-slate-500">Module sử dụng · chọn nhiều</p><div className="mt-2 flex flex-wrap gap-1.5">{([['pomodoro','🍅 Pomodoro'],['quiz','📝 Làm đề'],['deepStudy','🧠 Hiểu tận gốc'],['achievement','🏆 Thành tích'],['journal','📔 Nhật ký'],['antiProcrastination','🎯 Chống trì hoãn'],['global','🌍 Dùng chung']] as [ContentModule,string][]).map(([value,label]) => <button key={value} type="button" onClick={() => toggleContentModule(value)} className={`rounded-lg px-2 py-1 text-[10px] font-bold ${contentDraft.modules.includes(value) ? 'bg-[#2e7d32] text-white' : 'bg-[#eff9ef] text-[#2e7d32]'}`}>{label}</button>)}</div></div><div className="grid grid-cols-2 gap-3"><select aria-label="Mascot nội dung mới" value={contentDraft.mascot} onChange={(event) => setContentDraft({ ...contentDraft, mascot: event.target.value as typeof contentDraft.mascot })} className="input"><option value="lumi">🐝 Lumi</option><option value="lumi-sad">🐝 Lumi đang buồn</option><option value="lumi-cheer">🐝 Lumi động viên</option><option value="lumi-celebrate">🐝 Lumi ăn mừng</option><option value="ong">🐝 Ong vàng</option></select><select aria-label="Mức độ nội dung mới" value={contentDraft.tone} onChange={(event) => setContentDraft({ ...contentDraft, tone: event.target.value as ContentTone })} className="input"><option value="gentle">Nhẹ nhàng</option><option value="normal">Bình thường</option><option value="positive">Tích cực</option><option value="humorous">Hài hước</option><option value="highEnergy">Cực kỳ động viên</option></select></div><button className="primary-button w-full" onClick={addCustomContent}><CirclePlus className="h-4 w-4" />Thêm vào kho nội dung</button></div><ContentRows items={visibleContentItems} selectedIds={selectedContentIds} onSelected={setSelectedContentIds} onToggle={(id: string) => save({ customContent: contentItems.map((item) => item.id === id ? { ...item, enabled: !item.enabled } : item) }, "Đã cập nhật nội dung.")} onTrash={(ids: string[]) => trashContent(ids)} onRestore={(ids: string[]) => restoreContent(ids)} onPermanentDelete={(ids: string[]) => permanentlyDeleteContent(ids)} />
      </EditorCard>
      <EditorCard icon={MessageCircle} eyebrow="Mascot theo trạng thái" title="Lumi & Ong · 17 trạng thái" text="Gán ảnh, mô tả và điều kiện sử dụng cho từng trạng thái. Mascot đã tắt sẽ không được chọn; xóa sẽ chuyển vào thùng rác.">
        <div className="grid gap-3"><select aria-label="Trạng thái mascot" value={mascotDraft.id} onChange={(event) => setMascotDraft({ ...mascotDraft, id: event.target.value })} className="input"><option value="idle">idle · bình thường</option><option value="happy">happy · vui</option><option value="studying">studying · đang học</option><option value="focus">focus · tập trung</option><option value="tired">tired · mệt</option><option value="sleepy">sleepy · buồn ngủ</option><option value="procrastinating">procrastinating · trì hoãn</option><option value="encouragement">encouragement · động viên</option><option value="achievement">achievement · thành tích</option><option value="mistake">mistake · an ủi lỗi sai</option><option value="comeback">comeback · quay lại</option><option value="streak">streak · giữ chuỗi</option><option value="level_up">level_up · lên cấp</option><option value="deep_focus">deep_focus · hiểu sâu</option><option value="break">break · nghỉ</option><option value="almost_done">almost_done · gần xong</option><option value="completed">completed · hoàn thành</option></select><input aria-label="Tên trạng thái mascot" className="input" value={mascotDraft.name} onChange={(event) => setMascotDraft({ ...mascotDraft, name: event.target.value })} placeholder="Tên trạng thái" /><textarea aria-label="Mô tả trạng thái mascot" className="input min-h-20" value={mascotDraft.description} onChange={(event) => setMascotDraft({ ...mascotDraft, description: event.target.value })} placeholder="Lumi đang làm gì?" /><input aria-label="Điều kiện sử dụng mascot" className="input" value={mascotDraft.condition} onChange={(event) => setMascotDraft({ ...mascotDraft, condition: event.target.value })} placeholder="Điều kiện sử dụng" /><input aria-label="URL ảnh mascot trạng thái" className="input" value={mascotDraft.imageUrl} onChange={(event) => setMascotDraft({ ...mascotDraft, imageUrl: event.target.value })} placeholder="URL ảnh; bỏ trống để dùng fallback" /><button className="primary-button w-full" onClick={addMascotState}><CirclePlus className="h-4 w-4" />Lưu trạng thái mascot</button></div>
        <MascotRows items={mascotItems} selectedIds={selectedMascotIds} onSelected={setSelectedMascotIds} onToggle={(id: string) => save({ mascotStates: mascotItems.map((item) => item.id === id ? { ...item, enabled: !item.enabled, updatedAt: new Date().toISOString() } : item) }, "Đã cập nhật trạng thái mascot.")} onEdit={updateMascot} onTrash={trashMascot} onRestore={restoreMascot} onPermanentDelete={permanentlyDeleteMascot} />
      </EditorCard>
      <EditorCard icon={Gift} eyebrow="Xác suất có trọng số" title="Cấu hình phần thưởng" text="Mỗi phần thưởng có loại, giá trị, tỷ lệ và màu nhận diện. Tổng tỷ lệ được cân đối theo trọng số khi quay.">
        <div className="grid gap-3"><label className="block text-sm font-bold">Vé quay khi mở mốc có mảnh ghép<input aria-label="Số vé quay cấp khi mở mốc" value={ticketGrant} onChange={(event) => setTicketGrant(event.target.value)} type="number" min="0" max="20" className="input mt-1" /><small className="mt-1 block text-xs font-normal text-slate-500">Giá trị hiện tại: {config.wheelTicketsPerAchievement ?? 1} vé cho mỗi thành tích có thưởng mảnh ghép.</small></label><button className="secondary-button w-full" onClick={saveTicketGrant}>Lưu số vé quay</button><input aria-label="Tên phần thưởng vòng quay" value={reward.label} onChange={(event) => setReward({ ...reward, label: event.target.value })} className="input" placeholder="Tên phần thưởng" /><div className="grid grid-cols-2 gap-3"><select aria-label="Loại phần thưởng vòng quay" value={reward.kind} onChange={(event) => setReward({ ...reward, kind: event.target.value as RewardKind })} className="input"><option value="xp">XP</option><option value="fragment">Mảnh ghép</option><option value="badge">Huy hiệu</option><option value="ticket">Vé quay</option><option value="item">Vật phẩm</option></select><input aria-label="Giá trị phần thưởng" value={reward.value} onChange={(event) => setReward({ ...reward, value: event.target.value })} type="number" min="0" className="input" placeholder="Giá trị" /></div><div className="grid grid-cols-[1fr_auto] gap-3"><input aria-label="Trọng số xác suất phần thưởng" value={reward.probability} onChange={(event) => setReward({ ...reward, probability: event.target.value })} type="number" min="0" className="input" placeholder="Trọng số" /><input aria-label="Màu phần thưởng" value={reward.color} onChange={(event) => setReward({ ...reward, color: event.target.value })} type="color" className="h-11 w-12 rounded-xl border border-amber-200 bg-transparent p-1 dark:border-amber-400/30" /></div><button className="primary-button w-full" onClick={addReward}><CirclePlus className="h-4 w-4" />Thêm phần thưởng</button></div>
        <ConfigRows rows={config.wheelRewards.map((entry) => ({ id: entry.id, title: entry.label, meta: `${entry.kind} · ${entry.value} · trọng số ${entry.probability}`, enabled: true, color: entry.color }))} onDelete={(id) => save({ wheelRewards: config.wheelRewards.filter((entry) => entry.id !== id) }, "Đã xóa phần thưởng vòng quay.")} />
      </EditorCard>
    </section>
    <AdminInlineEditors config={config} onConfig={onConfig} />
  </>;
}

function EditorCard({ icon: Icon, eyebrow, title, text, children }: { icon: typeof Award; eyebrow: string; title: string; text: string; children: React.ReactNode }) {
  return <section className="panel p-5"><div className="flex gap-3"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-2xl bg-amber-100 text-amber-800 dark:bg-amber-500/20 dark:text-amber-200"><Icon className="h-5 w-5" /></span><div><p className="text-xs font-bold uppercase tracking-[.14em] text-amber-700 dark:text-amber-300">{eyebrow}</p><h2 className="mt-1 font-display text-xl font-bold">{title}</h2><p className="mt-2 text-sm leading-6 text-slate-500">{text}</p></div></div><div className="mt-5">{children}</div></section>;
}

function ContentRows({ items, selectedIds, onSelected, onToggle, onTrash, onRestore, onPermanentDelete }: { items: CustomContentItem[]; selectedIds: string[]; onSelected: (ids: string[]) => void; onToggle: (id: string) => void; onTrash: (ids: string[]) => void; onRestore: (ids: string[]) => void; onPermanentDelete: (ids: string[]) => void }) {
  const active = items.filter((item) => !item.deletedAt);
  const trash = items.filter((item) => Boolean(item.deletedAt));
  const toggleSelected = (id: string) => onSelected(selectedIds.includes(id) ? selectedIds.filter((item) => item !== id) : [...selectedIds, id]);
  const selectAll = (list: CustomContentItem[]) => { const ids = list.map((item) => item.id); onSelected(ids.every((id) => selectedIds.includes(id)) ? selectedIds.filter((id) => !ids.includes(id)) : Array.from(new Set([...selectedIds, ...ids]))); };
  const rows = (list: CustomContentItem[], isTrash: boolean) => list.length ? <div className="mt-3 max-h-72 space-y-2 overflow-auto pr-1">{list.map((item) => <article key={item.id} className="flex items-start gap-3 rounded-2xl border border-amber-100 p-3 dark:border-amber-400/15"><input aria-label={`Chọn ${item.text}`} type="checkbox" checked={selectedIds.includes(item.id)} onChange={() => toggleSelected(item.id)} className="mt-1" /><span className={`mt-1 h-3 w-3 shrink-0 rounded-full ${isTrash ? "bg-slate-400" : item.enabled ? "bg-emerald-500" : "bg-slate-300"}`} /><div className="min-w-0 flex-1"><b className="block text-sm">{item.text}</b><small className="block text-xs text-slate-500">{item.modules.join(", ")} · {item.contexts.join(", ")} · {item.mascot} · {item.tone}{item.deletedAt ? ` · Xóa ${new Date(item.deletedAt).toLocaleDateString()}` : ""}</small></div>{!isTrash && <button aria-label={`${item.enabled ? "Tắt" : "Bật"} ${item.text}`} onClick={() => onToggle(item.id)} className={cn("rounded-lg px-2 py-1 text-xs font-bold", item.enabled ? "bg-emerald-100 text-emerald-800 dark:bg-emerald-400/15 dark:text-emerald-200" : "bg-slate-100 text-slate-600 dark:bg-white/10 dark:text-slate-300")}>{item.enabled ? "Đang dùng" : "Tạm ẩn"}</button>}</article>)}</div> : <p className="mt-3 rounded-2xl bg-amber-50 p-3 text-sm text-amber-900 dark:bg-amber-500/10 dark:text-amber-100">Chưa có nội dung trong khu vực này.</p>;
  const bulk = (action: (ids: string[]) => void) => { if (selectedIds.length) action(selectedIds); };
  return <div className="mt-5 space-y-5"><section><div className="flex flex-wrap items-center justify-between gap-2"><div><h3 className="font-bold text-[#2e7d32]">Đang sử dụng / tạm ẩn</h3><p className="text-xs text-slate-500">Nội dung tạm ẩn không được bộ chọn sử dụng.</p></div><div className="flex gap-2"><button type="button" className="secondary-button" onClick={() => selectAll(active)}>☑ Chọn tất cả</button><button type="button" className="secondary-button" disabled={!selectedIds.some((id) => active.some((item) => item.id === id))} onClick={() => bulk((ids) => onTrash(ids.filter((id) => active.some((item) => item.id === id))))}>🗑️ Thùng rác</button></div></div>{rows(active, false)}</section><section><div className="flex flex-wrap items-center justify-between gap-2"><div><h3 className="font-bold text-slate-700 dark:text-slate-200">🗑️ Thùng rác</h3><p className="text-xs text-slate-500">Có thể khôi phục hoặc xóa vĩnh viễn sau khi xác nhận.</p></div><div className="flex gap-2"><button type="button" className="secondary-button" onClick={() => selectAll(trash)}>☑ Chọn tất cả</button><button type="button" className="secondary-button" disabled={!selectedIds.some((id) => trash.some((item) => item.id === id))} onClick={() => bulk((ids) => onRestore(ids.filter((id) => trash.some((item) => item.id === id))))}>↩ Khôi phục</button><button type="button" className="secondary-button text-rose-700" disabled={!selectedIds.some((id) => trash.some((item) => item.id === id))} onClick={() => bulk((ids) => onPermanentDelete(ids.filter((id) => trash.some((item) => item.id === id))))}>🗑️ Xóa vĩnh viễn</button></div></div>{rows(trash, true)}</section></div>;
}

function MascotRows({ items, selectedIds, onSelected, onToggle, onEdit, onTrash, onRestore, onPermanentDelete }: { items: MascotStateItem[]; selectedIds: string[]; onSelected: (ids: string[]) => void; onToggle: (id: string) => void; onEdit: (id: string) => void; onTrash: (ids: string[]) => void; onRestore: (ids: string[]) => void; onPermanentDelete: (ids: string[]) => void }) {
  const active = items.filter((item) => !item.deletedAt);
  const trash = items.filter((item) => Boolean(item.deletedAt));
  const toggle = (id: string) => onSelected(selectedIds.includes(id) ? selectedIds.filter((item) => item !== id) : [...selectedIds, id]);
  const selectAll = (list: MascotStateItem[]) => { const ids = list.map((item) => item.id); onSelected(ids.every((id) => selectedIds.includes(id)) ? selectedIds.filter((id) => !ids.includes(id)) : Array.from(new Set([...selectedIds, ...ids]))); };
  const bulk = (action: (ids: string[]) => void, list: MascotStateItem[]) => { const ids = selectedIds.filter((id) => list.some((item) => item.id === id)); if (ids.length) action(ids); };
  const rows = (list: MascotStateItem[], isTrash: boolean) => list.length ? <div className="mt-3 max-h-80 space-y-2 overflow-auto pr-1">{list.map((item) => <article key={item.id} className="flex items-start gap-3 rounded-2xl border border-amber-100 p-3 dark:border-amber-400/15"><input aria-label={`Chọn mascot ${item.name}`} type="checkbox" checked={selectedIds.includes(item.id)} onChange={() => toggle(item.id)} className="mt-1" />{item.imageUrl ? <img src={item.imageUrl} alt={item.name} className="h-10 w-10 rounded-xl object-cover" onError={(event) => { event.currentTarget.style.display = "none"; }} /> : <span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[#fff3cd] text-xl">🐝</span>}<div className="min-w-0 flex-1"><b className="block text-sm">{item.name} <span className="text-xs font-normal text-slate-500">({item.id})</span></b><small className="block text-xs leading-5 text-slate-500">{item.description} · Dùng khi: {item.condition}{item.deletedAt ? ` · Xóa ${new Date(item.deletedAt).toLocaleDateString()}` : ""}</small></div>{!isTrash && <><button aria-label={`Sửa ${item.name}`} onClick={() => onEdit(item.id)} className="secondary-button px-2 py-1 text-xs">Sửa</button><button aria-label={`${item.enabled ? "Tắt" : "Bật"} ${item.name}`} onClick={() => onToggle(item.id)} className={cn("rounded-lg px-2 py-1 text-xs font-bold", item.enabled ? "bg-emerald-100 text-emerald-800 dark:bg-emerald-400/15 dark:text-emerald-200" : "bg-slate-100 text-slate-600 dark:bg-white/10 dark:text-slate-300")}>{item.enabled ? "Đang dùng" : "Tạm ẩn"}</button></> }</article>)}</div> : <p className="mt-3 rounded-2xl bg-amber-50 p-3 text-sm text-amber-900 dark:bg-amber-500/10 dark:text-amber-100">Chưa có mascot trong khu vực này.</p>;
  return <div className="mt-5 space-y-5"><section><div className="flex flex-wrap items-center justify-between gap-2"><div><h3 className="font-bold text-[#2e7d32]">Đang dùng / tạm ẩn</h3><p className="text-xs text-slate-500">Mascot tạm ẩn sẽ không được tự động chọn.</p></div><div className="flex gap-2"><button type="button" className="secondary-button" onClick={() => selectAll(active)}>☑ Chọn tất cả</button><button type="button" className="secondary-button" disabled={!selectedIds.some((id) => active.some((item) => item.id === id))} onClick={() => bulk(onTrash, active)}>🗑️ Thùng rác</button></div></div>{rows(active, false)}</section><section><div className="flex flex-wrap items-center justify-between gap-2"><div><h3 className="font-bold text-slate-700 dark:text-slate-200">🗑️ Thùng rác mascot</h3><p className="text-xs text-slate-500">Khôi phục hoặc xóa vĩnh viễn sau xác nhận.</p></div><div className="flex gap-2"><button type="button" className="secondary-button" onClick={() => selectAll(trash)}>☑ Chọn tất cả</button><button type="button" className="secondary-button" disabled={!selectedIds.some((id) => trash.some((item) => item.id === id))} onClick={() => bulk(onRestore, trash)}>↩ Khôi phục</button><button type="button" className="secondary-button text-rose-700" disabled={!selectedIds.some((id) => trash.some((item) => item.id === id))} onClick={() => bulk(onPermanentDelete, trash)}>🗑️ Xóa vĩnh viễn</button></div></div>{rows(trash, true)}</section></div>;
}

function ConfigRows({ rows, onToggle, onDelete }: { rows: { id: string; title: string; meta: string; enabled: boolean; color?: string }[]; onToggle?: (id: string) => void; onDelete: (id: string) => void }) {
  if (!rows.length) return <p className="mt-5 rounded-2xl bg-amber-50 p-4 text-sm leading-6 text-amber-900 dark:bg-amber-500/10 dark:text-amber-100">Chưa có nội dung do quản trị viên tạo.</p>;
  return <div className="mt-5 max-h-72 space-y-2 overflow-auto pr-1">{rows.map((row) => <article className="flex items-center gap-3 rounded-2xl border border-amber-100 p-3 dark:border-amber-400/15" key={row.id}><span className="h-3 w-3 shrink-0 rounded-full" style={{ backgroundColor: row.color ?? (row.enabled ? "#d99a28" : "#9a8c78") }} /><div className="min-w-0 flex-1"><b className="block truncate text-sm">{row.title}</b><small className="block truncate text-xs text-slate-500">{row.meta}</small></div>{onToggle && <button aria-label={`${row.enabled ? "Tắt" : "Bật"} ${row.title}`} onClick={() => onToggle(row.id)} className={cn("rounded-lg px-2 py-1 text-xs font-bold", row.enabled ? "bg-emerald-100 text-emerald-800 dark:bg-emerald-400/15 dark:text-emerald-200" : "bg-slate-100 text-slate-600 dark:bg-white/10 dark:text-slate-300")}>{row.enabled ? "Bật" : "Tắt"}</button>}<button aria-label={`Xóa ${row.title}`} onClick={() => onDelete(row.id)} className="icon-button h-8 w-8 text-rose-600"><Trash2 className="h-4 w-4" /></button></article>)}</div>;
}

function AdminInlineEditors({ config, onConfig }: Pick<Props, "config" | "onConfig">) {
  const save = (patch: Partial<AppConfig>, message: string) => onConfig({ ...config, ...patch, updatedAt: new Date().toISOString() }, message);
  const updateEncouragement = (event: FormEvent<HTMLFormElement>, id: string) => {
    event.preventDefault(); const form = new FormData(event.currentTarget); const text = String(form.get("text") || "").trim();
    if (!text) return toast.error("Nội dung lời động viên không được để trống.");
    save({ encouragements: config.encouragements.map((entry) => entry.id === id ? { ...entry, text, type: String(form.get("type")) as Encouragement["type"], enabled: form.get("enabled") === "on" } : entry) }, "Đã lưu lời động viên.");
  };
  const updateAchievement = (event: FormEvent<HTMLFormElement>, id: string) => {
    event.preventDefault(); const form = new FormData(event.currentTarget); const name = String(form.get("name") || "").trim(); const threshold = Math.max(1, Number(form.get("threshold")) || 0);
    if (!name || !threshold) return toast.error("Tên và mốc điều kiện phải hợp lệ.");
    save({ customAchievements: config.customAchievements.map((entry) => entry.id === id ? { ...entry, name, description: String(form.get("description") || "").trim(), metric: String(form.get("metric")) as AchievementMetric, threshold, rewardXp: Math.max(0, Number(form.get("rewardXp")) || 0), rewardFragments: Math.max(0, Number(form.get("rewardFragments")) || 0), title: String(form.get("title") || "").trim() || undefined, titleMeaning: String(form.get("titleMeaning") || "").trim() || undefined, lumiImageUrl: String(form.get("lumiImageUrl") || "").trim() || undefined, enabled: form.get("enabled") === "on" } : entry) }, "Đã lưu mốc thành tích.");
  };
  const updateReward = (event: FormEvent<HTMLFormElement>, id: string) => {
    event.preventDefault(); const form = new FormData(event.currentTarget); const label = String(form.get("label") || "").trim();
    if (!label) return toast.error("Tên phần thưởng không được để trống.");
    save({ wheelRewards: config.wheelRewards.map((entry) => entry.id === id ? { ...entry, label, kind: String(form.get("kind")) as RewardKind, value: Math.max(0, Number(form.get("value")) || 0), probability: Math.max(0, Number(form.get("probability")) || 0), color: String(form.get("color") || entry.color) } : entry) }, "Đã lưu phần thưởng vòng quay.");
  };
  const updateCharacter = (event: FormEvent<HTMLFormElement>, id: string) => {
    event.preventDefault(); const form = new FormData(event.currentTarget); const sourceName = String(form.get("sourceName") || "").trim(); const sourceUrl = String(form.get("sourceUrl") || "").trim(); const imageUrl = String(form.get("imageUrl") || "").trim(); const imageSource = String(form.get("imageSource") || "").trim();
    if (!sourceName || !sourceUrl || !imageUrl || !imageSource) return toast.error("Nguồn nội dung và nguồn ảnh không được để trống.");
    let timeline: HistoricalCharacter["timeline"];
    try { const parsed = JSON.parse(String(form.get("timeline") || "[]")); if (!Array.isArray(parsed)) throw new Error("invalid"); timeline = parsed.filter((item) => item && typeof item === "object").map((item) => ({ id: String(item.id || uid()), title: String(item.title || "Mốc lịch sử"), content: String(item.content || ""), requiredFragments: Math.max(0, Number(item.requiredFragments) || 0) })); } catch { return toast.error("Timeline phải là JSON mảng hợp lệ."); }
    save({ characters: config.characters.map((entry) => entry.id === id ? { ...entry, sourceName, sourceUrl, imageUrl, imageSource, timeline, updatedAt: new Date().toISOString() } : entry) }, "Đã lưu nguồn và timeline nhân vật.");
  };
  const Group = ({ title, description, children }: { title: string; description: string; children: React.ReactNode }) => <details className="panel mt-5 p-5"><summary className="cursor-pointer list-none"><p className="text-xs font-bold uppercase tracking-[.14em] text-amber-700 dark:text-amber-300">Biên tập trực tiếp</p><h2 className="mt-1 font-display text-xl font-bold">{title}</h2><p className="mt-2 text-sm leading-6 text-slate-500">{description}</p></summary><div className="mt-5 space-y-3">{children}</div></details>;
  return <section className="mt-7" aria-labelledby="admin-edit-title"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-amber-700 dark:text-amber-300">Cập nhật cấu hình</p><h2 id="admin-edit-title" className="mt-2 font-display text-2xl font-bold">Chỉnh sửa nội dung đã tạo</h2><p className="mt-2 max-w-3xl text-sm leading-6 text-slate-500">Mở từng mục để điều chỉnh nội dung và tham số thay vì phải xóa rồi tạo lại. Lưu từng biểu mẫu để cập nhật cấu hình chung.</p></div>
    <Group title="Lời động viên" description="Chỉnh sửa câu chữ, bối cảnh phản hồi và trạng thái hiển thị.">{config.encouragements.length ? config.encouragements.map((entry) => <form key={entry.id} onSubmit={(event) => updateEncouragement(event, entry.id)} className="rounded-2xl border border-amber-100 p-4 dark:border-amber-400/15"><div className="grid gap-3 sm:grid-cols-[1fr_auto_auto]"><textarea aria-label={`Nội dung lời động viên ${entry.text}`} name="text" defaultValue={entry.text} className="input mt-0 min-h-20" /><select aria-label={`Loại lời động viên ${entry.text}`} name="type" defaultValue={entry.type} className="input mt-0"><option value="correct">Trả lời đúng</option><option value="incorrect">Trả lời chưa đúng</option></select><label className="inline-flex items-center gap-2 text-sm font-bold"><input aria-label={`Trạng thái lời động viên ${entry.text}`} name="enabled" type="checkbox" defaultChecked={entry.enabled} />Hiển thị</label></div><button className="secondary-button mt-3" type="submit">Lưu chỉnh sửa</button></form>) : <p className="text-sm text-slate-500">Chưa có lời động viên để chỉnh sửa.</p>}</Group>
    <Group title="Thành tích tùy chỉnh" description="Điều chỉnh điều kiện, phần thưởng XP/mảnh ghép và trạng thái công bố.">{config.customAchievements.length ? config.customAchievements.map((entry) => <form key={entry.id} onSubmit={(event) => updateAchievement(event, entry.id)} className="rounded-2xl border border-amber-100 p-4 dark:border-amber-400/15"><div className="grid gap-3 md:grid-cols-2"><input aria-label={`Tên thành tích ${entry.name}`} name="name" defaultValue={entry.name} className="input mt-0" /><input aria-label={`Mô tả thành tích ${entry.name}`} name="description" defaultValue={entry.description} className="input mt-0" /><input aria-label={`Danh hiệu thành tích ${entry.name}`} name="title" defaultValue={entry.title ?? ""} className="input mt-0" placeholder="Danh hiệu" /><input aria-label={`Ý nghĩa danh hiệu ${entry.name}`} name="titleMeaning" defaultValue={entry.titleMeaning ?? ""} className="input mt-0" placeholder="Ý nghĩa danh hiệu" /><input aria-label={`URL ảnh Lumi ${entry.name}`} name="lumiImageUrl" defaultValue={entry.lumiImageUrl ?? ""} className="input mt-0" placeholder="URL ảnh Lumi riêng (tùy chọn)" /><select aria-label={`Chỉ số thành tích ${entry.name}`} name="metric" defaultValue={entry.metric} className="input mt-0"><option value="xp">XP</option><option value="learnedCards">Thẻ đã nhớ</option><option value="completedQuizzes">Đề hoàn thành</option><option value="completedSets">Bộ hoàn tất</option></select><input aria-label={`Mốc điều kiện ${entry.name}`} name="threshold" defaultValue={entry.threshold} type="number" min="1" className="input mt-0" /><input aria-label={`XP phần thưởng ${entry.name}`} name="rewardXp" defaultValue={entry.rewardXp} type="number" min="0" className="input mt-0" /><input aria-label={`Mảnh ghép phần thưởng ${entry.name}`} name="rewardFragments" defaultValue={entry.rewardFragments} type="number" min="0" className="input mt-0" /></div><label className="mt-3 inline-flex items-center gap-2 text-sm font-bold"><input aria-label={`Trạng thái thành tích ${entry.name}`} name="enabled" type="checkbox" defaultChecked={entry.enabled} />Công bố thành tích này</label><button className="secondary-button ml-3 mt-3" type="submit">Lưu chỉnh sửa</button></form>) : <p className="text-sm text-slate-500">Chưa có mốc tùy chỉnh để chỉnh sửa.</p>}</Group>
    <Group title="Phần thưởng vòng quay" description="Điều chỉnh tên, loại, giá trị, trọng số và màu của từng phần thưởng.">{config.wheelRewards.length ? config.wheelRewards.map((entry) => <form key={entry.id} onSubmit={(event) => updateReward(event, entry.id)} className="rounded-2xl border border-amber-100 p-4 dark:border-amber-400/15"><div className="grid gap-3 md:grid-cols-5"><input aria-label={`Tên phần thưởng ${entry.label}`} name="label" defaultValue={entry.label} className="input mt-0 md:col-span-2" /><select aria-label={`Loại phần thưởng ${entry.label}`} name="kind" defaultValue={entry.kind} className="input mt-0"><option value="xp">XP</option><option value="fragment">Mảnh ghép</option><option value="badge">Huy hiệu</option><option value="ticket">Vé quay</option><option value="item">Vật phẩm</option></select><input aria-label={`Giá trị phần thưởng ${entry.label}`} name="value" defaultValue={entry.value} type="number" min="0" className="input mt-0" /><input aria-label={`Trọng số phần thưởng ${entry.label}`} name="probability" defaultValue={entry.probability} type="number" min="0" className="input mt-0" /></div><div className="mt-3 flex items-center gap-3"><label className="text-sm font-bold" htmlFor={`color-${entry.id}`}>Màu hiển thị</label><input id={`color-${entry.id}`} aria-label={`Màu phần thưởng ${entry.label}`} name="color" defaultValue={entry.color} type="color" className="h-10 w-12 rounded-xl border border-amber-200 bg-transparent p-1 dark:border-amber-400/30" /><button className="secondary-button" type="submit">Lưu chỉnh sửa</button></div></form>) : <p className="text-sm text-slate-500">Chưa có phần thưởng để chỉnh sửa.</p>}</Group>
    <Group title="Nhân vật, nguồn và timeline" description="Chỉnh sửa trực tiếp nguồn nội dung, nguồn ảnh, liên kết ảnh và các mốc lịch sử của nhân vật.">{config.characters.length ? config.characters.map((entry) => <form key={entry.id} onSubmit={(event) => updateCharacter(event, entry.id)} className="rounded-2xl border border-amber-100 p-4 dark:border-amber-400/15"><p className="font-bold">{entry.name}</p><div className="mt-3 grid gap-3 md:grid-cols-2"><input aria-label={`Nguồn nội dung ${entry.name}`} name="sourceName" defaultValue={entry.sourceName} className="input mt-0" placeholder="Tên nguồn nội dung" /><input aria-label={`Liên kết nguồn nội dung ${entry.name}`} name="sourceUrl" defaultValue={entry.sourceUrl} className="input mt-0" placeholder="URL nguồn nội dung" /><input aria-label={`Liên kết ảnh ${entry.name}`} name="imageUrl" defaultValue={entry.imageUrl} className="input mt-0" placeholder="URL ảnh" /><input aria-label={`Nguồn ảnh ${entry.name}`} name="imageSource" defaultValue={entry.imageSource} className="input mt-0" placeholder="Nguồn ảnh" /></div><textarea aria-label={`Timeline ${entry.name}`} name="timeline" defaultValue={JSON.stringify(entry.timeline, null, 2)} className="input mt-3 min-h-36 font-mono text-xs" /><button className="secondary-button mt-3" type="submit">Lưu nhân vật</button></form>) : <p className="text-sm text-slate-500">Chưa có nhân vật để chỉnh sửa.</p>}</Group>
  </section>;
}
